parts.text:
{
  "title": "두부와 함께한 산책 기록",
  "cards": [
    {
      "stamp_id": "stamp:e03",
      "title": "상가 밀집 지역으로 이동",
      "text": "등록 상가가 산재한 구간에서 등록 상가가 모인 구간으로 이동하였다."
    },
    {
      "stamp_id": "stamp:e04",
      "title": "두부의 냄새 맡기",
      "text": "등록 상가가 모인 구간에서 두부가 냄새를 맡았으며 이전 공간 이동으로부터 120초가 경과하였다."
    },
    {
      "stamp_id": "stamp:e06",
      "title": "늘벗근린공원 인근으로 이동",
      "text": "등록 상가가 모인 구간에서 늘벗근린공원 인근으로 이동하였으며 이전 공간 관측으로부터 240초가 경과하였다."
    },
    {
      "stamp_id": "stamp:e07",
      "title": "공원에서의 기념 촬영",
      "text": "늘벗근린공원 인근에서 두부와 함께 사진을 찍었으며 이전 행동 기록으로부터 300초, 공간 이동으로부터 120초가 경과하였다."
    },
    {
      "stamp_id": "stamp:e09",
      "title": "양재천 인근으로 이동",
      "text": "늘벗근린공원 인근에서 양재천 인근으로 이동하였으며 이전 공간 관측으로부터 300초가 경과하였다."
    },
    {
      "stamp_id": "stamp:e10",
      "title": "상가 밀집 지역으로 복귀",
      "text": "양재천 인근에서 등록 상가가 모인 구간으로 이동하였으며 이전 공간 관측으로부터 240초가 경과하였다."
    },
    {
      "stamp_id": "stamp:e11",
      "title": "상가 적은 구간으로 이동",
      "text": "등록 상가가 모인 구간에서 등록 상가가 적은 구간으로 이동하였으며 이전 공간 관측으로부터 180초가 경과하였다."
    }
  ]
}
